import { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { getResults, getJob, updateShortlist } from "../services/api";

function ScoreRing({ score, color = "var(--blue)", size = 56 }) {
  const r = 20; const circ = 2 * Math.PI * r;
  const dash = (score / 100) * circ;
  return (
    <div style={{ position: "relative", width: size, height: size, flexShrink: 0 }}>
      <svg width={size} height={size} viewBox="0 0 56 56">
        <circle cx="28" cy="28" r={r} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth="4"/>
        <circle cx="28" cy="28" r={r} fill="none" stroke={color} strokeWidth="4"
          strokeDasharray={`${dash} ${circ}`} strokeLinecap="round"
          transform="rotate(-90 28 28)" style={{ transition: "stroke-dasharray 0.8s ease" }}/>
      </svg>
      <div style={{
        position: "absolute", inset: 0, display: "flex",
        alignItems: "center", justifyContent: "center",
        fontFamily: "Plus Jakarta Sans", fontWeight: 700, fontSize: 13,
        color: "var(--text-primary)",
      }}>{Math.round(score)}</div>
    </div>
  );
}

function PassivityBadge({ score, label }) {
  const color = score >= 70 ? "#FCD34D" : score >= 40 ? "#60A5FA" : "#2DD4BF";
  const bg = score >= 70 ? "rgba(245,158,11,0.1)" : score >= 40 ? "rgba(59,130,246,0.1)" : "rgba(20,184,166,0.1)";
  return (
    <div style={{
      display: "inline-flex", alignItems: "center", gap: 6,
      background: bg, borderRadius: 8, padding: "4px 10px",
      border: `1px solid ${color}30`,
    }}>
      <div style={{ width: 6, height: 6, borderRadius: "50%", background: color }} />
      <span style={{ fontSize: 11, fontWeight: 600, color, fontFamily: "Plus Jakarta Sans" }}>{label}</span>
    </div>
  );
}

function ExplanationPanel({ breakdown, onClose }) {
  if (!breakdown) return null;
  return (
    <div style={{
      position: "fixed", inset: 0, background: "rgba(0,0,0,0.7)",
      zIndex: 200, display: "flex", alignItems: "center", justifyContent: "center",
      padding: 24, animation: "fadeIn 0.2s ease",
    }} onClick={onClose}>
      <div style={{
        background: "var(--navy-2)", borderRadius: 20, padding: 36,
        maxWidth: 560, width: "100%", border: "1px solid var(--border)",
        maxHeight: "80vh", overflowY: "auto",
      }} onClick={e => e.stopPropagation()}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 28 }}>
          <h3 style={{ fontFamily: "Plus Jakarta Sans", fontWeight: 700, fontSize: 20 }}>Score Explanation</h3>
          <button onClick={onClose} style={{ background: "none", border: "none", color: "var(--text-muted)", cursor: "pointer", fontSize: 22 }}>×</button>
        </div>

        {/* Scores */}
        <div style={{ display: "flex", gap: 16, marginBottom: 28 }}>
          {[
            { label: "Job Fit", value: breakdown.fit_score, color: "var(--blue)" },
            { label: "Passivity", value: breakdown.passivity_score, color: "#FCD34D" },
          ].map(s => (
            <div key={s.label} style={{
              flex: 1, background: "var(--navy-3)", borderRadius: 12, padding: "16px",
              border: "1px solid var(--border)", textAlign: "center",
            }}>
              <ScoreRing score={s.value} color={s.color} size={64} />
              <div style={{ marginTop: 8, fontSize: 12, color: "var(--text-secondary)", fontFamily: "Plus Jakarta Sans", fontWeight: 600 }}>{s.label}</div>
            </div>
          ))}
        </div>

        {/* Fit explanation */}
        <div style={{ marginBottom: 24 }}>
          <div className="label" style={{ marginBottom: 8 }}>Qualification match</div>
          <div style={{ background: "var(--navy-3)", borderRadius: 10, padding: 16, fontSize: 14, color: "var(--text-secondary)", lineHeight: 1.6, border: "1px solid var(--border)" }}>
            {breakdown.fit_explanation}
          </div>
        </div>

        {/* Passivity factors */}
        <div>
          <div className="label" style={{ marginBottom: 4 }}>{breakdown.passivity_context_title}</div>
          <div style={{ fontSize: 12, color: "var(--text-muted)", marginBottom: 12 }}>{breakdown.passivity_context_note}</div>
          <div style={{ display: "grid", gap: 8 }}>
            {(breakdown.passivity_factors || []).map((f, i) => (
              <div key={i} style={{
                background: "var(--navy-3)", borderRadius: 10, padding: "12px 14px",
                border: "1px solid var(--border)", display: "flex", gap: 12, alignItems: "flex-start",
              }}>
                <div style={{ fontSize: 16, marginTop: 1 }}>
                  {f.impact === "positive" ? "✅" : f.impact === "negative" ? "⚠️" : "ℹ️"}
                </div>
                <div>
                  <div style={{ fontFamily: "Plus Jakarta Sans", fontWeight: 600, fontSize: 13, color: "var(--text-primary)", marginBottom: 2 }}>{f.factor}</div>
                  <div style={{ fontSize: 12, color: "var(--text-secondary)" }}>{f.detail}</div>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div style={{ marginTop: 24, padding: "14px 16px", background: "rgba(59,130,246,0.08)", borderRadius: 10, border: "1px solid rgba(59,130,246,0.2)", fontSize: 13, color: "var(--text-secondary)", lineHeight: 1.6 }}>
          {breakdown.summary}
        </div>
      </div>
    </div>
  );
}

export default function Results() {
  const { jobId } = useParams();
  const navigate = useNavigate();
  const [candidates, setCandidates] = useState([]);
  const [job, setJob] = useState(null);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({ skill_filter: "", seniority: "" });
  const [selected, setSelected] = useState(null);
  const [shortlisted, setShortlisted] = useState(new Set());

  useEffect(() => {
    Promise.all([getJob(jobId), getResults(jobId)])
      .then(([j, r]) => { setJob(j.data); setCandidates(r.data); })
      .catch(() => alert("Could not load results."))
      .finally(() => setLoading(false));
  }, [jobId]);

  const applyFilters = async () => {
    const params = {};
    if (filters.skill_filter) params.skill_filter = filters.skill_filter;
    if (filters.seniority)    params.seniority = filters.seniority;
    const res = await getResults(jobId, params);
    setCandidates(res.data);
  };

  const toggleShortlist = async (c) => {
    const newStatus = shortlisted.has(c.id) ? "pending" : "approved";
    await updateShortlist(jobId, c.id, newStatus);
    setShortlisted(s => { const n = new Set(s); newStatus === "approved" ? n.add(c.id) : n.delete(c.id); return n; });
  };

  if (loading) return (
    <div style={{ textAlign: "center", padding: 80, color: "var(--text-secondary)" }}>
      <div style={{ fontSize: 40, marginBottom: 16 }}>⚙️</div>
      <div style={{ fontFamily: "Plus Jakarta Sans", fontSize: 18 }}>Loading results...</div>
    </div>
  );

  return (
    <div style={{ animation: "fadeUp 0.5s ease" }}>
      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 36 }}>
        <div>
          <div className="badge badge-blue" style={{ marginBottom: 12 }}>Step 3 of 3 — Results</div>
          <h1 style={{ fontFamily: "Plus Jakarta Sans", fontWeight: 800, fontSize: 32, color: "var(--text-primary)", marginBottom: 6 }}>
            {job?.title || "Results"}
          </h1>
          <p style={{ color: "var(--text-secondary)", fontSize: 15 }}>
            {candidates.length} candidates ranked by job-fit score
          </p>
        </div>
        <div style={{ display: "flex", gap: 10 }}>
          <button className="btn-secondary" onClick={() => navigate(`/upload/${jobId}`)}>← Re-upload</button>
          {shortlisted.size > 0 && (
            <button className="btn-primary" onClick={() => navigate(`/shortlist/${jobId}`)}>
              Review Shortlist ({shortlisted.size}) →
            </button>
          )}
        </div>
      </div>

      {/* Filters */}
      <div className="card" style={{ padding: "20px 24px", marginBottom: 24, display: "flex", gap: 16, alignItems: "flex-end" }}>
        <div style={{ flex: 1 }}>
          <label className="label">Filter by skill</label>
          <input className="input" placeholder="e.g. Python, Java, Agile..."
            value={filters.skill_filter} onChange={e => setFilters(f => ({ ...f, skill_filter: e.target.value }))} />
        </div>
        <div style={{ width: 180 }}>
          <label className="label">Seniority</label>
          <select className="input" value={filters.seniority}
            onChange={e => setFilters(f => ({ ...f, seniority: e.target.value }))}>
            <option value="">All levels</option>
            <option value="senior">Senior</option>
            <option value="mid">Mid-level</option>
            <option value="junior">Junior</option>
          </select>
        </div>
        <button className="btn-primary" onClick={applyFilters} style={{ marginBottom: 1 }}>Apply</button>
        <button className="btn-secondary" onClick={() => { setFilters({ skill_filter: "", seniority: "" }); getResults(jobId).then(r => setCandidates(r.data)); }}
          style={{ marginBottom: 1 }}>Clear</button>
      </div>

      {/* Candidate list */}
      <div style={{ display: "grid", gap: 14 }}>
        {candidates.map((c, i) => (
          <div key={c.id} className="card" style={{
            padding: "20px 24px", display: "flex", gap: 20, alignItems: "center",
            animation: `fadeUp 0.4s ease ${i * 0.05}s both`,
            borderColor: shortlisted.has(c.id) ? "rgba(59,130,246,0.4)" : "var(--border)",
          }}>
            {/* Rank */}
            <div style={{
              width: 36, height: 36, borderRadius: 10, flexShrink: 0,
              background: i < 3 ? "rgba(59,130,246,0.15)" : "var(--navy-3)",
              display: "flex", alignItems: "center", justifyContent: "center",
              fontFamily: "Plus Jakarta Sans", fontWeight: 700,
              fontSize: 14, color: i < 3 ? "#60A5FA" : "var(--text-muted)",
            }}>#{i + 1}</div>

            {/* Info */}
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 6, flexWrap: "wrap" }}>
                <span style={{ fontFamily: "Plus Jakarta Sans", fontWeight: 700, fontSize: 16, color: "var(--text-primary)" }}>
                  {c.name || `Candidate ${c.id}`}
                </span>
                {c.seniority_level && (
                  <span className={`badge badge-${c.seniority_level === "senior" ? "blue" : c.seniority_level === "mid" ? "teal" : "gray"}`}>
                    {c.seniority_level}
                  </span>
                )}
                <PassivityBadge score={c.passivity_score} label={c.score_breakdown?.passivity_label || "—"} />
              </div>
              <div style={{ fontSize: 13, color: "var(--text-secondary)", marginBottom: 8 }}>
                {c.current_title && <span>{c.current_title}</span>}
                {c.current_company && <span> · {c.current_company}</span>}
                {c.years_experience > 0 && <span> · {c.years_experience}y exp</span>}
              </div>
              {c.skills && (
                <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                  {c.skills.split(",").slice(0, 5).map(s => (
                    <span key={s} className="badge badge-gray" style={{ fontSize: 11 }}>{s.trim()}</span>
                  ))}
                </div>
              )}
            </div>

            {/* Scores */}
            <div style={{ display: "flex", gap: 20, alignItems: "center" }}>
              <div style={{ textAlign: "center" }}>
                <ScoreRing score={c.fit_score} color="var(--blue)" />
                <div style={{ fontSize: 10, color: "var(--text-muted)", marginTop: 4, fontFamily: "Plus Jakarta Sans", fontWeight: 600 }}>FIT</div>
              </div>
              <div style={{ textAlign: "center" }}>
                <ScoreRing score={c.passivity_score} color="#FCD34D" />
                <div style={{ fontSize: 10, color: "var(--text-muted)", marginTop: 4, fontFamily: "Plus Jakarta Sans", fontWeight: 600 }}>PASSIVITY</div>
              </div>
            </div>

            {/* Actions */}
            <div style={{ display: "flex", gap: 8, flexShrink: 0 }}>
              <button className="btn-secondary" style={{ padding: "8px 14px", fontSize: 12 }}
                onClick={() => setSelected(c.score_breakdown)}>
                Explain
              </button>
              <button onClick={() => toggleShortlist(c)} style={{
                padding: "8px 14px", borderRadius: 8, fontSize: 12, cursor: "pointer",
                fontFamily: "Plus Jakarta Sans", fontWeight: 600, border: "none", transition: "all 0.2s",
                background: shortlisted.has(c.id) ? "rgba(59,130,246,0.2)" : "var(--navy-3)",
                color: shortlisted.has(c.id) ? "#60A5FA" : "var(--text-secondary)",
              }}>
                {shortlisted.has(c.id) ? "✓ Shortlisted" : "+ Shortlist"}
              </button>
            </div>
          </div>
        ))}

        {candidates.length === 0 && (
          <div style={{ textAlign: "center", padding: 60, color: "var(--text-muted)" }}>
            <div style={{ fontSize: 40, marginBottom: 12 }}>🔍</div>
            <div style={{ fontFamily: "Plus Jakarta Sans", fontSize: 16 }}>No candidates match the current filters</div>
          </div>
        )}
      </div>

      {selected && <ExplanationPanel breakdown={selected} onClose={() => setSelected(null)} />}
    </div>
  );
}
